<style scoped lang="scss" src="./d-element-library-menu-item.scss"></style>

<template>
  <li class="DElementLibraryMenuItem">
    <button
      class="DElementLibraryMenuItem__Button"
      @click="handleClick(item.value)"
    >
      <Icon :shape="item.icon" :color="'black'"></Icon>
      {{ item.label }}
      <div class="DElementLibraryMenuItem__ArrowIcon">
        <Icon :shape="IconShape.RIGHT" :color="'black'"></Icon>
      </div>
    </button>
  </li>
</template>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Button from "../../button/button";
import { ButtonMode } from "../../button/button.constants";
import Icon from "../../icon/icon";
import { IconShape } from "../../icon/icon.constants";

@Component({
  components: {
    Button,
    Icon,
  },
})
export default class DElementLibraryMenuItem extends Vue {
  @Prop({
    type: Object,
    required: true,
  })
  item;

  get ButtonMode() {
    return ButtonMode;
  }

  get IconShape() {
    return IconShape;
  }

  handleClick(page) {
    this.$emit("click", page);
  }
}
</script>
